  "why.hero.title": { en: "Digital Infrastructure Intelligence &mdash; not a category. A convergence.", es: "Inteligencia en Infraestructura Digital &mdash; no es una categoría. Es una convergencia." },
  "why.hero.lede": { en: "Mission, vision, strategic positioning and the long-term ambition behind International Network Advisors.", es: "Misión, visión, posicionamiento estratégico y la ambición de largo plazo detrás de International Network Advisors." },
  "why.vision.eyebrow": { en: "Vision", es: "Visión" },
  "why.vision.title": { en: "To become the leading international advisory platform for digital infrastructure, project structuring and AI-enabled investment intelligence.", es: "Convertirnos en la plataforma internacional líder de asesoría en infraestructura digital, estructuración de proyectos e inteligencia de inversión potenciada por IA." },
  "why.vision.p1": { en: "International Network Advisors (INA) was conceived with a clear ambition: to redefine how governments, development banks, investors and technology companies identify, structure, finance and implement digital infrastructure projects.", es: "International Network Advisors (INA) fue concebida con una ambición clara: redefinir cómo gobiernos, bancos de desarrollo, inversores y empresas de tecnología identifican, estructuran, financian e implementan proyectos de infraestructura digital." },
  "why.vision.p2": { en: "Digital infrastructure is no longer limited to telecommunications networks. It now encompasses fiber optic backbones, submarine cable systems, hyperscale data centers, cloud infrastructure, artificial intelligence computing facilities, satellite constellations, smart energy systems and the digital ecosystems that support modern economies.", es: "La infraestructura digital ya no se limita a las redes de telecomunicaciones. Hoy abarca backbones de fibra óptica, sistemas de cables submarinos, centros de datos hyperscale, infraestructura cloud, instalaciones de cómputo de inteligencia artificial, constelaciones satelitales, sistemas energéticos inteligentes y los ecosistemas digitales que sostienen las economías modernas." },
  "why.vision.p3": { en: "Unlike traditional consulting firms, INA is designed from the ground up as an intellectual property company. Its competitive advantage is not based solely on consulting services but on proprietary methodologies, assessment models, digital tools and AI-powered advisory capabilities that can be reused across projects and jurisdictions.", es: "A diferencia de las consultoras tradicionales, INA está diseñada desde su origen como una empresa de propiedad intelectual. Su ventaja competitiva no se basa únicamente en servicios de consultoría, sino en metodologías propias, modelos de evaluación, herramientas digitales y capacidades de asesoría potenciadas por IA, reutilizables entre proyectos y jurisdicciones." },
  "why.mission.eyebrow": { en: "Mission", es: "Misión" },
  "why.mission.title": { en: "Transform complex opportunities into bankable, investable and sustainable projects.", es: "Transformar oportunidades complejas en proyectos bancables, invertibles y sostenibles." },
  "why.mission.lede": { en: "Through multidisciplinary expertise, structured methodologies and artificial intelligence, INA supports clients across the complete project lifecycle.", es: "A través de experiencia multidisciplinaria, metodologías estructuradas e inteligencia artificial, INA acompaña a sus clientes en todo el ciclo de vida del proyecto." },
  "why.mission.d1": { en: "<b>Opportunity Identification</b>Screening &amp; strategic assessment", es: "<b>Identificación de Oportunidades</b>Screening y evaluación estratégica" },
  "why.mission.d2": { en: "<b>Project Structuring</b>Technical &amp; regulatory feasibility", es: "<b>Estructuración de Proyectos</b>Factibilidad técnica y regulatoria" },
